/* Opt-in horizontal layout for native Frappe child-table grids.
 * Enable another table with retail.scrollable_grid.register(doctype, fieldname, options).
 * No global Grid/GridRow prototype changes; native controls handle edits and validation.
 */
(() => {
	window.retail = window.retail || {};
	if (retail.scrollable_grid) return;
	const SETTINGS = "RetailScrollableGrid";
	const registrations = new Set();

	// Display copies only: retain original DocFields for editors and calculations.
	function compactRateLabel(grid, df) {
		if (!["items", "custom_retail_packing_detail"].includes(grid.df.fieldname)) return df;
		const labels = {
			purchase_net_rate: "PR Excl VAT", purchase_gross_rate: "PR Incl VAT",
			selling_net_rate: "SR Excl VAT", selling_gross_rate: "SR Incl VAT",
			custom_purchase_net_rate: "PR Excl VAT", custom_purchase_gross_rate: "PR Incl VAT",
			custom_sales_net_rate: "SR Excl VAT", custom_sales_gross_rate: "SR Incl VAT",
			custom_amount_including_vat: "Amt Incl VAT", custom_vat_amount: "VAT Amt",
		};
		if (grid.df.fieldname === "custom_retail_packing_detail") {
			Object.assign(labels, {packing_name: "Pack Name", conversion_factor: "Conv fac"});
		}
		const type = grid.frm.doctype;
		const prefix = ["Purchase Order", "Purchase Receipt", "Purchase Invoice", "Supplier Quotation"].includes(type)
			? "PR" : ["Sales Order", "Delivery Note", "Sales Invoice", "POS Invoice", "Quotation"].includes(type) ? "SR" : null;
		if (prefix) {
			labels.rate = `${prefix} Excl VAT`;
			labels.custom_rate_including_vat = `${prefix} Incl VAT`;
		}
		return labels[df.fieldname] ? {...df, label: labels[df.fieldname]} : df;
	}

	function setupColumns() {
		if (this.visible_columns?.length) return;
		const own = frappe.get_user_settings(this.frm.doctype, SETTINGS) || {};
		const legacy = frappe.get_user_settings(this.frm.doctype, "GridView") || {};
		let saved = Object.prototype.hasOwnProperty.call(own, this.df.fieldname)
			? own[this.df.fieldname]
			: legacy[this.doctype];
		const defaults = retail.purchase_grid_defaults?.[this.frm.doctype]?.[this.doctype];
		if (defaults && (!Array.isArray(saved) || !saved.length)) {
			// Empty preferences can reach the browser even after migration. Use
			// native saved columns when present, otherwise the shipped defaults.
			const native = legacy[this.doctype];
			saved = Array.isArray(native) && native.length ? native : defaults;
		}
		this.user_defined_columns = (Array.isArray(saved) ? saved : []).flatMap((entry) => {
			const df = this.fields_map[entry.fieldname];
			return df ? [{ ...df, columns: entry.columns, width_px: entry.width_px, in_list_view: 1 }] : [];
		});
		let fields = this.user_defined_columns.length
			? this.user_defined_columns
			: this.editable_fields || this.docfields;
		if (this.fields_map.item_code?.options === "Item" && this.fields_map.custom_item_barcode) {
			// Apply the requested identity columns to existing saved layouts too.
			// Keep all other columns, widths and ordering intact.
			fields = fields.map(field => typeof field === "string" ? this.fields_map[field] : field).filter(Boolean);
			const existingName = fields.find(field => field.fieldname === "item_name") || this.fields_map.item_name;
			const name = existingName && {...existingName, in_list_view: 1, columns: existingName.columns || 2};
			const existingBarcode = fields.find(field => field.fieldname === "custom_item_barcode") || this.fields_map.custom_item_barcode;
			const barcode = {...existingBarcode, in_list_view: 1, columns: existingBarcode.columns || 2};
			fields = fields.filter(field => field.fieldname !== "custom_item_barcode");
			let index = fields.findIndex(field => field.fieldname === "item_name");
			if (name && index < 0) {
				index = fields.findIndex(field => field.fieldname === "item_code") + 1;
				fields.splice(index, 0, name);
			} else if (name) fields[index] = name;
			if (index >= 0) fields.splice(index + 1, 0, barcode);
			if (this.user_defined_columns.length) this.user_defined_columns = fields;
		}
		if (this.frm.doctype === "Sales Invoice" && this.df.fieldname === "items" && this.fields_map.uom) {
			const existing = fields.find(field => field.fieldname === "uom") || this.fields_map.uom;
			const uom = {...existing, hidden: 0, in_list_view: 1, columns: existing.columns || 1};
			fields = fields.filter(field => field.fieldname !== "uom");
			const index = fields.findIndex(field => field.fieldname === "custom_item_barcode");
			fields.splice(index + 1, 0, uom);
			if (this.user_defined_columns.length) this.user_defined_columns = fields;
		}
		if (this.frm.doctype === "Sales Invoice" && this.df.fieldname === "items"
			&& this.fields_map.custom_amount_including_vat) {
			fields = fields.map(field => typeof field === "string" ? this.fields_map[field] : field).filter(Boolean);
			const existing = fields.find(field => field.fieldname === "custom_amount_including_vat") ||
				this.fields_map.custom_amount_including_vat;
			const inclusive = {...existing, in_list_view: 1, columns: existing.columns || 2};
			fields = fields.filter(field => field.fieldname !== "custom_amount_including_vat");
			const index = fields.findIndex(field => field.fieldname === "amount");
			if (index >= 0) fields.splice(index + 1, 0, inclusive);
			if (this.user_defined_columns.length) this.user_defined_columns = fields;
		}
		if (this.retail_purchase_tracking || this.frm.doctype === "Stock Reconciliation") {
			// Tracking follows the selected Item even when a personal layout omits
			// these fields. Work on copies; retain saved widths and preferences.
			const names = this.frm.doctype === "Stock Reconciliation"
				? ["use_serial_batch_fields", "serial_no", "batch_no", "add_serial_batch_bundle", "serial_and_batch_bundle"]
				: ["serial_no", "batch_no"];
			const identity = names.map(name => fields.find(field => field.fieldname === name) ||
				(this.fields_map[name] && { ...this.fields_map[name], columns: 2, in_list_view: 1 }))
				.filter(Boolean).map(field => ({...field, in_list_view: 1, columns: field.columns || 2}));
			fields = fields.filter(field => !names.includes(field.fieldname));
			let anchor = fields.findIndex(field => field.fieldname === "uom");
			if (this.frm.doctype === "Stock Reconciliation") anchor = fields.findIndex(field => field.fieldname === "stock_uom");
			if (anchor < 0) anchor = fields.findIndex(field => field.fieldname === "item_name");
			if (anchor < 0) anchor = fields.findIndex(field => field.fieldname === "item_code");
			fields.splice(anchor + 1, 0, ...identity);
			if (this.user_defined_columns.length) this.user_defined_columns = fields;
		}
		// A promotion's selected target stays visible even if saved columns omit it.
		const target = this.retail_promotion_target;
		if (target && this.fields_map[target]) {
			fields = [this.fields_map[target], ...fields.filter(field =>
				(typeof field === "string" ? field : field.fieldname) !== target)];
			if (this.user_defined_columns.length) this.user_defined_columns = fields;
		}
		if (this.frm.doctype === "Product Conversion" && this.df.fieldname === "items" && this.fields_map.bom_no) {
			// Keep the source BOM visible after existing personal columns.
			const bom = fields.find(field => field.fieldname === "bom_no") || this.fields_map.bom_no;
			fields = fields.filter(field => (typeof field === "string" ? field : field.fieldname) !== "bom_no");
			fields.push({...bom, in_list_view: 1, columns: bom.columns || 2});
			if (this.user_defined_columns.length) this.user_defined_columns = fields;
		}
		if (this.frm.doctype === "BOM" && this.df.fieldname === "items" && this.fields_map.custom_item_barcode) {
			const names = ["item_name", "custom_item_barcode"];
			const identity = names.map(name => ({...(fields.find(field => field.fieldname === name) || this.fields_map[name]), in_list_view: 1, columns: 2}));
			fields = fields.filter(field => !names.includes(typeof field === "string" ? field : field.fieldname));
			const index = fields.findIndex(field => (typeof field === "string" ? field : field.fieldname) === "item_code");
			fields.splice(index + 1, 0, ...identity);
			if (this.user_defined_columns.length) this.user_defined_columns = fields;
		}
		this.visible_columns = [];
		const seen = new Set();
		for (const field of fields) {
			const original = typeof field === "string" ? this.fields_map[field] : field;
			const df = original && compactRateLabel(this, original);
			if (
				!df ||
				seen.has(df.fieldname) ||
				df.hidden ||
				!(this.editable_fields || df.in_list_view) ||
				!this.frm.get_perm(df.permlevel, "read") ||
				frappe.model.layout_fields.includes(df.fieldtype)
			)
				continue;
			seen.add(df.fieldname);
			// Keep native formatters and metadata; only replace the width budget.
			this.update_default_colsize(df);
			df.colsize = Math.max(1, Math.min(12, Number(df.columns) || df.colsize || 1));
			if (df.fieldtype === "Link" && !df.formatter && df.parent) {
				const formatter = frappe.meta.docfield_map[df.parent]?.[df.fieldname]?.formatter;
				if (formatter) df.formatter = formatter;
			}
			// Item identity and Item Name are separate columns. Keep the native link
			// destination while displaying its stored code instead of the title.
			if (df.fieldname === "item_code" && df.fieldtype === "Link" && df.options === "Item") {
				const title = this.__retail_scroll_options?.item_code_as_title;
				df.formatter = (value, field, options, doc) =>
					frappe.form.formatters.Link(value, field, { ...options,
						label: title ? doc?.item_name || frappe.utils.get_link_title("Item", value) || value : value }, doc);
			}
			this.visible_columns.push([df, df.colsize]);
		}
	}

	function saveColumns(row, columns) {
		const save = retail.column_preferences?.supports(row.frm.doctype)
			? retail.column_preferences.save
			: frappe.model.user_settings.save.bind(frappe.model.user_settings);
		return save(row.frm.doctype, SETTINGS, {
			[row.grid.df.fieldname]: columns,
		}).then((r) => {
			frappe.model.user_settings[row.frm.doctype] = r.message || r;
			row.grid.reset_grid();
		});
	}

	function configureHeader(grid) {
		const row = grid.header_row;
		if (!row || row.__retail_scroll_header) return;
		row.__retail_scroll_header = true;
		row.validate_columns_width = function () {
			if (!this.selected_columns_for_grid?.length) {
				frappe.throw(__("Select at least one column."));
			}
			for (const entry of this.selected_columns_for_grid) {
				const width = Number(entry.columns);
				if (!Number.isInteger(width) || width < 1 || width > 12) {
					frappe.throw(__("Each column width must be a whole number from 1 to 12."));
				}
			}
		};
		row.update_user_settings_for_grid = function () {
			return saveColumns(this, this.selected_columns_for_grid);
		};
		row.reset_user_settings_for_grid = function () {
			return saveColumns(this, []);
		};
		// Native dialog reads global metadata widths; display this table's saved widths instead.
		const render = row.render_selected_columns;
		row.render_selected_columns = function (...args) {
			const result = render.apply(this, args);
			for (const entry of this.selected_columns_for_grid || []) {
				$(this.fields_html_wrapper)
					.find(".column-width")
					.filter(function () {
						return this.dataset.fieldname === entry.fieldname;
					})
					.val(entry.columns)
					.attr("value", entry.columns);
			}
			$(this.fields_html_wrapper).find(".column-width").on("change.retailPixels", event => {
				const entry = this.selected_columns_for_grid.find(column => column.fieldname === event.target.dataset.fieldname);
				if (entry) delete entry.width_px;
			});
			return result;
		};

		const sortColumns = row.sort_columns;
		if (sortColumns) row.sort_columns = function (...args) {
			const pixels = new Map((this.selected_columns_for_grid || []).map(entry => [entry.fieldname, entry.width_px]));
			const result = sortColumns.apply(this, args);
			for (const entry of this.selected_columns_for_grid) {
				if (Number.isFinite(pixels.get(entry.fieldname))) entry.width_px = pixels.get(entry.fieldname);
			}
			return result;
		};

		const setupDialog = row.setup_columns_for_dialog;
		if (setupDialog) row.setup_columns_for_dialog = function (...args) {
			const result = setupDialog.apply(this, args);
			for (const entry of this.selected_columns_for_grid) {
				const df = grid.visible_columns.find(([df]) => df.fieldname === entry.fieldname)?.[0];
				if (Number.isFinite(df?.width_px)) entry.width_px = df.width_px;
			}
			return result;
		};
	}

	function gridRows(grid) {
		// Frappe pagination deletes off-page slots and leaves holes. A hole is
		// not a row; reading it throws and skips the restyle for the visible page.
		return (grid.grid_rows || []).filter(row => row?.doc || row?.row);
	}

	function widthSignature(grid) {
		const parts = [];
		const measured = [];
		const packing = grid.df.fieldname === "custom_retail_packing_detail";
		for (const [df] of grid.visible_columns || []) {
			parts.push(df.fieldname, df.label, df.columns, df.colsize, df.width_px);
			const compact = compactRateLabel(grid, df) !== df;
			// Saved, pixel, and packing widths do not depend on cell text.
			// Including every value made each added line remeasure the whole table.
			if (packing && ["packing_name", "barcode", "packing_uom", "conversion_factor",
				"purchase_net_rate", "purchase_gross_rate", "selling_net_rate", "selling_gross_rate",
				"is_fast_plu_item"].includes(df.fieldname)) continue;
			if (!compact && (Number.isFinite(df.width_px) || grid.user_defined_columns?.some(column => column.fieldname === df.fieldname))) continue;
			measured.push(df);
		}
		for (const row of gridRows(grid)) {
			for (const df of measured) parts.push(row.doc?.[df.fieldname]);
		}
		return parts.join("\u0001");
	}

	// Measure formatted text, not the current cell box (which already has a fixed width).
	function contentWidths(grid) {
		const widths = {};
		const canvas = typeof document !== "undefined" ? document.createElement("canvas") : null;
		const context = canvas?.getContext("2d");
		const font = typeof getComputedStyle === "function"
			? getComputedStyle(grid.wrapper[0]).font : "14px sans-serif";
		if (context) context.font = font || "14px sans-serif";
		const measure = (text) => {
			const lines = String(text ?? "").split(/\r?\n/);
			return Math.max(0, ...lines.map((line) =>
				context ? context.measureText(line).width : line.length * 7));
		};
		const packingWidths = grid.df.fieldname === "custom_retail_packing_detail" ? {
			packing_name: 260, barcode: 200, packing_uom: 72, conversion_factor: 90,
			purchase_net_rate: 112, purchase_gross_rate: 112,
			selling_net_rate: 112, selling_gross_rate: 112, is_fast_plu_item: 72,
		} : {};
		for (const [df] of grid.visible_columns || []) {
			if (packingWidths[df.fieldname]) {
				widths[df.fieldname] = packingWidths[df.fieldname];
				continue;
			}
			const compact = compactRateLabel(grid, df) !== df;
			if (!compact && Number.isFinite(df.width_px)) {
				widths[df.fieldname] = df.width_px;
				continue;
			}
			if (!compact && grid.user_defined_columns?.some(column => column.fieldname === df.fieldname)) {
				widths[df.fieldname] = Math.max(1, Math.min(12, Number(df.columns) || df.colsize || 1)) * 80;
				continue;
			}
			let width = measure(__(df.label || df.fieldname)) + 40;
			for (const row of gridRows(grid)) {
				const value = row.doc?.[df.fieldname];
				let text = value ?? "";
				if (frappe.format && value != null) {
					const html = frappe.format(value, df, { inline: true }, row.doc);
					const element = document.createElement("div");
					element.innerHTML = html;
					text = element.textContent || "";
				}
				width = Math.max(width, measure(text) + 32);
			}
			widths[df.fieldname] = Math.ceil(Math.min(320, Math.max(64, width)));
		}
		return widths;
	}

	function styleRow(grid, row) {
		if (!row?.row) return;
		if (row.doc && !row.__retail_item_name_search && grid.fields_map.item_code?.options === "Item") {
			row.__retail_item_name_search = true;
			const makeControl = row.make_control;
			row.make_control = function (column) {
				if (column.df.fieldname !== "item_name") return makeControl.call(this, column);
				if (column.field) return;
				// A second native Item selector writes item_code, so ERPNext runs
				// the same item, UOM, price and tax handlers from either column.
				const df = { ...grid.fields_map.item_code, label: column.df.label, formatter: undefined };
				const field = frappe.ui.form.make_control({
					df, parent: column.field_area, only_input: true, with_link_btn: true,
					doc: this.doc, doctype: this.doc.doctype, docname: this.doc.name,
					frm: grid.frm, grid, grid_row: this,
				});
				field.get_query = (...args) => {
					const query = grid.get_field("item_code").get_query;
					return typeof query === "function" ? query(...args) : query;
				};
				field.is_title_link = () => true;
				field.refresh();
				field.$input?.addClass("input-sm").attr("placeholder", __("Search Item Name"));
				this.set_arrow_keys(field);
				column.field = field;
				this.on_grid_fields_dict.item_name = field;
				this.on_grid_fields.push(field);
			};
		}
		const itemColumn = (grid.visible_columns || []).find(([df]) =>
			df.fieldname === "item_code" && df.fieldtype === "Link" && df.options === "Item");
		if (row.doc && itemColumn?.[0]?.formatter) {
			// Native rows keep their own field copies for subsequent refreshes.
			const field = row.docfields?.find(df => df.fieldname === "item_code");
			if (field) field.formatter = itemColumn[0].formatter;
			const cell = row.columns?.item_code?.static_area;
			const html = itemColumn[0].formatter(row.doc.item_code, itemColumn[0], {}, row.doc);
			if (cell && cell.html() !== html) cell.html(html);
		}
		// Native GridRow takes heading labels from its own DocFields, not visible_columns.
		if (!row.doc) {
			// make_head puts this handler back on every redraw. It focuses row 0,
			// and the keyboard reveal then scrolls the page to that first line.
			row.row?.find?.("[tabindex]")?.removeAttr?.("tabindex")?.off?.("focus");
			for (const [df] of grid.visible_columns || []) {
				if (compactRateLabel(grid, df) === df) continue;
				const cell = row.columns?.[df.fieldname];
				cell?.static_area?.text(__(df.label));
				cell?.attr("title", __(grid.fields_map[df.fieldname]?.label || df.label));
			}
		}
		const options = grid.__retail_scroll_options;
		// Native search cells omit data-fieldname; use their field map so they
		// receive the same sizing and pinned position as headings and item cells.
		for (const [fieldname, cell] of Object.entries(row.search_columns || {})) {
			if (cell?.[0]) cell[0].dataset.fieldname = fieldname;
		}
		const cells = row.row[0]?.children && Array.from(row.row[0].children);
		const signature = JSON.stringify([grid.__retail_content_widths, options?.pin_field,
			grid.__retail_resizing, (grid.visible_columns || []).map(([df]) => df.fieldname)]);
		if (cells && row.__retail_cell_style === signature && row.__retail_styled_cells?.length === cells.length &&
			cells.every((cell, index) => cell === row.__retail_styled_cells[index])) return;
		row.row.children(".col").each(function () {
			const fieldname = this.dataset.fieldname;
			const column = (grid.visible_columns || []).find(([df]) => df.fieldname === fieldname);
			const width = column
				? grid.__retail_content_widths?.[fieldname] || 80
				: this.classList.contains("row-index")
				? 56
				: 40;
			this.style.setProperty("--retail-column-width", `${width}px`);
			const grow = grid.df.fieldname === "custom_retail_packing_detail"
				? ({packing_name: 2, barcode: 1}[fieldname] || 0) : width;
			this.style.setProperty("--retail-column-grow", column && fieldname !== grid.__retail_resizing ? String(grow) : "0");
			this.classList.toggle("retail-grid-data-column", Boolean(column));
			this.classList.toggle("retail-grid-pinned", fieldname === options?.pin_field && grid.visible_columns?.[0]?.[0]?.fieldname === fieldname);
		});
		// Use native touch scrolling. Keep touchstart: native touch-click focus
		// handling still needs the container references initialized by that handler.
		row.row.children("[data-fieldname]").off("touchmove");
		if (cells) {
			row.__retail_cell_style = signature;
			row.__retail_styled_cells = cells;
		}
	}


	function currentColumns(grid) {
		return grid.visible_columns.map(([df]) => ({
			fieldname: df.fieldname,
			columns: Math.max(1, Math.min(12, Number(df.columns) || df.colsize || 1)),
			...(Number.isFinite(df.width_px) ? { width_px: df.width_px } : {}),
		}));
	}

	function configureDirectColumns(grid) {
		const header = grid.header_row;
		if (!header?.row?.[0] || header.__retail_direct_columns) return;
		header.__retail_direct_columns = true;
		let dragged;
		for (const cell of header.row[0].querySelectorAll(".retail-grid-data-column")) {
			cell.draggable = true;
			cell.title = __("Drag to move column; drag the edge to resize.");
			cell.addEventListener("dragstart", event => {
				dragged = cell.dataset.fieldname;
				event.dataTransfer.setData("text/plain", dragged);
				event.dataTransfer.effectAllowed = "move";
			});
			cell.addEventListener("dragover", event => {
				if (dragged) { event.preventDefault(); event.dataTransfer.dropEffect = "move"; }
			});
			cell.addEventListener("drop", event => {
				if (!dragged) return;
				event.preventDefault();
				const columns = currentColumns(grid);
				const source = columns.findIndex(column => column.fieldname === dragged);
				const target = columns.findIndex(column => column.fieldname === cell.dataset.fieldname);
				if (source >= 0 && target >= 0 && source !== target) {
					columns.splice(target, 0, columns.splice(source, 1)[0]);
					saveColumns(header, columns);
				}
				dragged = null;
			});
			cell.addEventListener("dragend", () => { dragged = null; });
			const handle = document.createElement("span");
			handle.className = "retail-grid-resize-handle";
			handle.title = __("Drag to resize column");
			handle.addEventListener("pointerdown", event => {
				event.preventDefault();
				event.stopPropagation();
				cell.draggable = false;
				const start = event.clientX;
				const width = cell.getBoundingClientRect().width;
				const columns = currentColumns(grid);
				const column = columns.find(column => column.fieldname === cell.dataset.fieldname);
				for (const entry of columns) {
					const heading = Array.from(header.row[0].children).find(element => element.dataset.fieldname === entry.fieldname);
					entry.width_px = Math.round(heading?.getBoundingClientRect().width || grid.__retail_content_widths[entry.fieldname]);
					grid.__retail_content_widths[entry.fieldname] = entry.width_px;
				}
				grid.__retail_resizing = column.fieldname;
				const direction = frappe.utils.is_rtl() ? -1 : 1;
				const move = event => {
					const pixels = Math.round(Math.max(64, Math.min(960, width + direction * (event.clientX - start))));
					column.width_px = pixels;
					grid.__retail_content_widths[column.fieldname] = pixels;
					grid.wrapper[0].style.setProperty("--retail-grid-width", `${138 + Object.values(grid.__retail_content_widths).reduce((sum, value) => sum + value, 0)}px`);
					[header, grid.header_search, ...gridRows(grid)].forEach(row => styleRow(grid, row));
				};
				const finish = () => {
					document.removeEventListener("pointermove", move);
					document.removeEventListener("pointerup", finish);
					document.removeEventListener("pointercancel", cancel);
					cell.draggable = true;
					for (const entry of columns) {
						const heading = Array.from(header.row[0].children).find(element => element.dataset.fieldname === entry.fieldname);
						entry.width_px = Math.round(heading?.getBoundingClientRect().width || entry.width_px);
					}
					delete grid.__retail_resizing;
					saveColumns(header, columns);
				};
				const cancel = () => {
					document.removeEventListener("pointermove", move);
					document.removeEventListener("pointerup", finish);
					document.removeEventListener("pointercancel", cancel);
					cell.draggable = true;
					delete grid.__retail_resizing;
					safeLayout(grid);
				};
				document.addEventListener("pointermove", move);
				document.addEventListener("pointerup", finish);
				document.addEventListener("pointercancel", cancel);
			});
			cell.appendChild(handle);
		}
	}

	function layout(grid) {
		if (!grid.wrapper || grid.__retail_resizing) return;
		grid.wrapper.addClass("retail-scrollable-grid");
		const container = grid.wrapper.find(".form-grid-container")[0];
		if (!container) return;
		container.setAttribute("aria-label", __("Scrollable table"));
		container.setAttribute("tabindex", "0");
		const signature = widthSignature(grid);
		if (signature !== grid.__retail_width_signature || !grid.__retail_content_widths) {
			grid.__retail_content_widths = contentWidths(grid);
			grid.__retail_width_signature = signature;
		}
		const totalWidth =
			138 +
			(grid.visible_columns || []).reduce(
				(sum, [df]) => sum + (grid.__retail_content_widths?.[df.fieldname] || 0),
				0
			);
		grid.wrapper[0].style.setProperty("--retail-grid-width", `${totalWidth}px`);
		configureHeader(grid);
		[grid.header_row, grid.header_search, ...gridRows(grid)].forEach((row) =>
			styleRow(grid, row)
		);
		configureDirectColumns(grid);
	}

	// Column styling must not abort native row rendering. Save and page changes
	// both call render_result_rows, and a throw there never reaches the server.
	function scrollPositions(grid) {
		const nodes = [];
		const add = (element) => {
			if (element && typeof element.scrollTop === "number" && !nodes.includes(element)) nodes.push(element);
		};
		const root = grid.wrapper?.[0];
		if (root?.querySelectorAll) root.querySelectorAll(".form-grid-container").forEach(add);
		let node = root;
		while (node) {
			add(node);
			node = node.parentElement;
		}
		if (typeof document !== "undefined") add(document.scrollingElement);
		return nodes.map((element) => ({element, top: element.scrollTop || 0, left: element.scrollLeft || 0}));
	}

	function restoreScroll(positions) {
		for (const {element, top, left} of positions || []) {
			if (element.scrollTop !== top) element.scrollTop = top;
			if (element.scrollLeft !== left) element.scrollLeft = left;
		}
	}

	function pageScroll() {
		const scrolling = typeof document !== "undefined" ? document.scrollingElement : null;
		return {x: window.scrollX || 0, y: window.scrollY || scrolling?.scrollTop || 0};
	}

	function holdPage(positions, page) {
		const jq = globalThis.jQuery || globalThis.$;
		try { jq?.("html, body")?.stop?.(true, false); } catch (error) { globalThis.console?.error?.(error); }
		restoreScroll(positions);
		if (!page || typeof window.scrollTo !== "function") return;
		const x = window.scrollX || 0;
		const y = window.scrollY || 0;
		if (x !== page.x || y !== page.y) window.scrollTo(page.x, page.y);
	}

	function keepPlace(positions, page) {
		holdPage(positions, page);
		for (const delay of [0, 120, 280]) setTimeout(() => holdPage(positions, page), delay);
	}

	// The heading is the first tab stop. Removing the active cell focuses it, and
	// its handler then opens row 0. Strip that before the body rows are rebuilt.
	function stripHeadingJump(grid) {
		grid.header_row?.row?.find?.("[tabindex]")?.removeAttr?.("tabindex")?.off?.("focus");
	}

	function parkFocus(grid) {
		const active = globalThis.document?.activeElement;
		const root = grid.wrapper?.[0];
		if (!active || active === document.body || !root?.contains?.(active)) return;
		const row = active.closest?.(".grid-row");
		grid.__retail_active_row = {
			name: row?.getAttribute?.("data-name") || "",
			field: active.getAttribute?.("data-fieldname")
				|| active.closest?.("[data-fieldname]")?.getAttribute?.("data-fieldname") || "",
		};
		let park = document.getElementById("retail-focus-park");
		if (!park) {
			park = document.createElement("div");
			park.id = "retail-focus-park";
			park.tabIndex = -1;
			park.setAttribute("aria-hidden", "true");
			park.style.cssText = "position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none";
			document.body.appendChild(park);
		}
		try { park.focus({preventScroll: true}); }
		catch (error) { park.focus(); }
	}

	function refocusEdited(grid) {
		const kept = grid.__retail_active_row;
		if (!kept?.name) return;
		const row = grid.grid_rows_by_docname?.[kept.name];
		const input = (kept.field && row?.on_grid_fields_dict?.[kept.field]?.$input?.[0])
			|| row?.row?.find?.("input,textarea,select")?.filter?.(":visible:first")?.[0];
		if (!input || document.activeElement === input) return;
		try { input.focus({preventScroll: true}); }
		catch (error) { input.focus?.(); }
	}

	function silenceScroll(grid) {
		if (typeof frappe === "undefined") return;
		frappe.flags = frappe.flags || {};
		const previous = frappe.flags.disable_auto_scroll;
		frappe.flags.disable_auto_scroll = true;
		globalThis.clearTimeout?.(grid.__retail_scroll_release);
		grid.__retail_scroll_release = setTimeout(() => {
			frappe.flags.disable_auto_scroll = previous;
		}, 400);
	}

	function safeLayout(grid) {
		try {
			layout(grid);
		} catch (error) {
			globalThis.console?.error?.(error);
		}
	}

	// Link suggestions must escape the overflow viewport. Keep the original UL and
	// its native selection handlers, moving it back as soon as autocomplete closes.
	function bindInteractions(grid) {
		let popup;
		const closePopup = () => {
			if (!popup) return;
			popup.parent.appendChild(popup.list);
			popup.host.remove();
			popup = null;
			window.removeEventListener("scroll", reposition, true);
			window.removeEventListener("resize", reposition);
		};
		const reposition = () => {
			if (!popup) return;
			if (!popup.input.isConnected || popup.list.hidden) {
				closePopup();
				return;
			}
			const rect = popup.input.getBoundingClientRect();
			const viewport = grid.wrapper.find(".form-grid-container")[0].getBoundingClientRect();
			if (
				rect.right < viewport.left ||
				rect.left > viewport.right ||
				rect.bottom < 0 ||
				rect.top > innerHeight
			) {
				popup.input.dispatchEvent(new Event("blur"));
				closePopup();
				return;
			}
			const width = Math.min(Math.max(rect.width,
				popup.list.classList.contains("retail-packing-results") ? 560 : 280), innerWidth - 16);
			const below = innerHeight - rect.bottom - 12;
			const above = below < 180 && rect.top > below;
			Object.assign(popup.host.style, {
				width: `${width}px`,
				left: `${Math.max(8, Math.min(rect.left, innerWidth - width - 8))}px`,
				top: above ? "auto" : `${rect.bottom}px`,
				bottom: above ? `${innerHeight - rect.top}px` : "auto",
			});
			popup.list.style.maxHeight = `${Math.max(
				60,
				Math.min(300, above ? rect.top - 12 : below)
			)}px`;
		};
		grid.wrapper
			.on("awesomplete-open.retailScroll", "input", function () {
				if (!this.closest(".data-row")) return;
				closePopup();
				const parent = this.closest(".awesomplete");
				const list = parent?.querySelector("ul");
				if (!list) return;
				const host = document.createElement("div");
				host.className = "awesomplete retail-grid-autocomplete";
				document.body.appendChild(host);
				host.appendChild(list);
				popup = { input: this, parent, list, host };
				reposition();
				window.addEventListener("scroll", reposition, true);
				window.addEventListener("resize", reposition);
			})
			.on("awesomplete-close.retailScroll", "input", closePopup);
		grid.wrapper.on(
			"focusin.retailScroll",
			".data-row input, .data-row select, .data-row textarea",
			function () {
				const cell = this.closest(".col");
				if (!cell || cell.classList.contains("retail-grid-pinned")) return;
				const container = grid.wrapper.find(".form-grid-container")[0];
				const bounds = container.getBoundingClientRect();
				const rect = cell.getBoundingClientRect();
				const pinned = this.closest(".data-row").querySelector(".retail-grid-pinned");
				const inset = innerWidth > 767 ? 96 + (pinned?.offsetWidth || 0) : 0;
				const rtl = frappe.utils.is_rtl();
				const left = bounds.left + (rtl ? 0 : inset);
				const right = bounds.right - (rtl ? inset : 0);
				if (rect.left < left) container.scrollLeft -= left - rect.left;
				else if (rect.right > right) container.scrollLeft += rect.right - right;
			}
		);
	}

	function enable(frm, fieldname, options = {}) {
		const grid = frm.fields_dict[fieldname]?.grid;
		// ERPNext supplies fallback templates even for editable Items grids.
		// Match native GridRow: the template is active only when editing is disabled.
		if (!grid || grid.__retail_scroll_options || (grid.template && !grid.meta?.editable_grid))
			return;
		grid.__retail_scroll_options = { pin_field: "item_code", ...options };
		grid.setup_visible_columns = setupColumns;
		// Rebuild cells only when a dynamic field change alters the layout (for
		// example, PI's Update Selling Price toggle). Other refreshes retain controls.
		const setupFields = grid.setup_fields;
		grid.setup_fields = function (...args) {
			const previous = JSON.stringify(
				(this.visible_columns || []).map(([df, width]) => [df.fieldname, width])
			);
			const result = setupFields.apply(this, args);
			this.visible_columns = [];
			this.setup_visible_columns();
			const current = JSON.stringify(
				this.visible_columns.map(([df, width]) => [df.fieldname, width])
			);
			if (previous !== current && this.grid_rows?.length) {
				this.grid_rows = [];
				this.wrapper.find(".grid-body .grid-row").remove();
			}
			return result;
		};
		// Page changes render a new set of rows without grid.refresh, so the
		// heading keeps its column widths and the new page falls back to native ones.
		const renderResultRows = grid.render_result_rows;
		if (typeof renderResultRows === "function" && !renderResultRows.__retail_page_layout) {
			grid.render_result_rows = function (...args) {
				parkFocus(this);
				silenceScroll(this);
				const positions = scrollPositions(this);
				const page = pageScroll();
				const result = renderResultRows.apply(this, args);
				stripHeadingJump(this);
				safeLayout(this);
				keepPlace(positions, page);
				return result;
			};
			grid.render_result_rows.__retail_page_layout = true;
		}
		const makeHead = grid.make_head;
		if (typeof makeHead === "function" && !makeHead.__retail_no_header_jump) {
			grid.make_head = function (...args) {
				const result = makeHead.apply(this, args);
				stripHeadingJump(this);
				return result;
			};
			grid.make_head.__retail_no_header_jump = true;
		}
		// Page changes and row edits call this to jump the window to the first line.
		grid.scroll_to_top = () => {};
		const pagination = grid.grid_pagination;
		if (pagination?.go_to_last_page_to_add_row && !pagination.__retail_keep_place) {
			pagination.__retail_keep_place = true;
			const goToLast = pagination.go_to_last_page_to_add_row;
			pagination.go_to_last_page_to_add_row = function (...args) {
				const scrollTo = frappe.utils.scroll_to;
				frappe.utils.scroll_to = () => {};
				try { return goToLast.apply(this, args); }
				finally { frappe.utils.scroll_to = scrollTo; }
			};
		}
		const focusRow = grid.set_focus_on_row;
		if (typeof focusRow === "function" && !focusRow.__retail_keep_place) {
			grid.set_focus_on_row = function (idx) {
				if (!this.allow_on_grid_editing?.()) return focusRow.call(this, idx);
				let index = idx == null && idx !== 0 ? (this.grid_rows?.length || 1) - 1 : idx;
				// The heading handler always asks for row 0. Stay on the row being edited.
				const keptName = idx === 0 ? this.__retail_active_row?.name : "";
				if (keptName) {
					const found = (this.grid_rows || []).findIndex(row => row?.doc?.name === keptName);
					if (found > 0) index = found;
				}
				const positions = scrollPositions(this);
				const page = pageScroll();
				const row = this.grid_rows?.[index];
				if (!row?.toggle_editable_row) return;
				const field = this.__retail_active_row?.field;
				setTimeout(() => {
					if (!row.row) return;
					row.toggle_editable_row(true);
					const input = (field && row.on_grid_fields_dict?.[field]?.$input?.[0])
						|| row.row.find?.('input[type="Text"],textarea,select')?.filter?.(":visible:first")?.[0];
					try { input?.focus?.({preventScroll: true}); }
					catch (error) { input?.focus?.(); }
					holdPage(positions, page);
				}, 100);
			};
			grid.set_focus_on_row.__retail_keep_place = true;
		}
		const refresh = grid.refresh;
		grid.refresh = function (...args) {
			// Item selection waits on this refresh. A styling error must not reject it.
			try {
				parkFocus(this);
				silenceScroll(this);
				const positions = scrollPositions(this);
				const page = pageScroll();
				const scroll = this.wrapper?.find(".form-grid-container").scrollLeft() || 0;
				const result = refresh.apply(this, args);
				stripHeadingJump(this);
				safeLayout(this);
				this.wrapper?.find(".form-grid-container").scrollLeft(scroll);
				keepPlace(positions, page);
				refocusEdited(this);
				holdPage(positions, page);
				return result;
			} catch (error) {
				globalThis.console?.error?.(error);
			}
		};
		const fitColumns = frappe.utils.debounce(() => safeLayout(grid), 100);
		grid.__retail_fit_columns = fitColumns;
		const refreshField = grid.refresh_field;
		if (refreshField) {
			grid.refresh_field = function (...args) {
				const result = refreshField.apply(this, args);
				fitColumns();
				return result;
			};
		}
		grid.debounced_refresh = frappe.utils.debounce(grid.refresh.bind(grid), 100);
		$(frm.wrapper).on(`grid-row-render.retailScroll_${fieldname}`, (_event, row) => {
			if (row.grid !== grid) return;
			try {
				styleRow(grid, row);
			} catch (error) {
				globalThis.console?.error?.(error);
			}
			fitColumns();
		});
		grid.reset_grid();
		bindInteractions(grid);
	}

	function register(doctype, fieldname, options = {}) {
		const key = `${doctype}:${fieldname}`;
		if (registrations.has(key)) return;
		registrations.add(key);
		frappe.ui.form.on(doctype, {
			refresh(frm) {
				enable(frm, fieldname, options);
			},
		});
	}
	retail.scrollable_grid = { enable, register,
		scheduleLayout(grid) { grid.__retail_fit_columns?.(); },
	};
	function boot() {
		if (!window.frappe?.ui?.form?.on) {
			setTimeout(boot, 100);
			return;
		}
		register("Purchase Order", "items");
		register("Purchase Invoice", "items");
		register("Purchase Receipt", "items");
		register("Material Request", "items");
		register("Stock Reconciliation", "items");
		register("Stock Entry", "items");
		register("Delivery Note", "items");
		register("Quotation", "items");
		register("Supplier Quotation", "items");
		register("Request for Quotation", "items");
		register("Sales Order", "items");
		register("Sales Invoice", "items");
		register("POS Invoice", "items");
		register("Promo Price", "products", { pin_field: "item" });
		register("Item", "custom_retail_packing_detail", {
			pin_field: "barcode",
		});
	}
	boot();
})();
